// =============================================================================
// APP.JS - CON REDIRECCIÓN AUTOMÁTICA Y RESTAURACIÓN DE SESIÓN
// =============================================================================
// MEJORAS:
// 1. ✅ Redirección automática al iniciar sesión
// 2. ✅ Restauración de sesión al recargar la página
// 3. ✅ Redirección a la página correcta según el rol
// =============================================================================

import React, { useState, useEffect } from 'react';
import { AuthProvider, useAuth } from './components/AuthContext';
import { CarritoProvider } from './components/CarritoContext';

// Importar componentes de páginas
import LoginPage from './components/LoginPage';
import ServiciosPage from './components/ServiciosPage';
import ServiciosClientePage from './components/ServiciosClientePage';

// Importar componentes de la página principal
import Header from './components/Header';
import MainContent from './components/MainContent';
import Footer from './components/Footer';
import './styles.css'; // Estilos globales de la pagiina principal.

// =============================================================================
// COMPONENTE INTERNO: AppContent
// =============================================================================
const AppContent = () => {

    // =========================================================================
    // 1. HOOKS Y ESTADOS
    // =========================================================================

    const { isAuthenticated, user, logout } = useAuth();
    const [currentPage, setCurrentPage] = useState('home');

    // =========================================================================
    // 2. EFECTO: RESTAURAR SESIÓN AL CARGAR LA APP
    // =========================================================================
    /**
     * Si el usuario ya estaba logueado (sesión en localStorage),
     * redirigir automáticamente a su página correspondiente
     * 
     * Este efecto solo se ejecuta una vez al montar el componente
     */
    useEffect(() => {
        if (isAuthenticated && user) {
            console.log('🔄 Sesión activa detectada, redirigiendo...');

            // Obtener página de redirección del usuario
            const redirectPage = user.redirectPage || getDefaultRedirect(user.role);

            // Redirigir a la página correcta
            setCurrentPage(redirectPage);

            console.log(`✅ Redirigido a: ${redirectPage}`);
        }
    }, []); // Solo ejecutar al montar (array vacío)

    // =========================================================================
    // 3. FUNCIONES DE NAVEGACIÓN
    // =========================================================================

    const goToHome = () => {
        setCurrentPage('home');
    };

    const goToLogin = () => {
        setCurrentPage('login');
    };

    const goToServicios = () => {
        setCurrentPage('servicios');
    };

    const goToServiciosCliente = () => {
        if (!isAuthenticated) {
            goToLogin();
        } else {
            setCurrentPage('servicios-cliente');
        }
    };

    const goToCotizacion = () => {
        alert('Página de cotización próximamente');
    };

    const goToPerfil = () => {
        alert('Página de perfil próximamente');
    };

    const handleLogout = () => {
        if (window.confirm('¿Estás seguro de que deseas cerrar sesión?')) {
            logout();
            goToHome();
        }
    };

    /**
     * Obtiene la página por defecto según el rol
     * Se usa como fallback si no hay redirectPage
     */
    const getDefaultRedirect = (role) => {
        switch (role) {
            case 'admin':
                return 'reportes';
            case 'trabajador':
                return 'tareas';
            case 'cliente':
                return 'servicios-cliente';
            default:
                return 'home';
        }
    };

    // =========================================================================
    // 4. MANEJADOR DE LOGIN EXITOSO
    // =========================================================================
    /**
     * Esta función se ejecuta cuando el login es exitoso
     * Recibe el resultado del login que incluye la página de redirección
     * 
     * @param {object} result - Resultado del login con { role, redirectPage }
     */
    const handleLoginSuccess = (result) => {
        console.log('✅ Login exitoso en App.js:', result);

        // Extraer rol y página de redirección
        const { role, redirectPage } = result;

        // Si hay página de redirección, usarla
        if (redirectPage) {
            console.log(`🔄 Redirigiendo a: ${redirectPage}`);
            setCurrentPage(redirectPage);
        } else {
            // Si no hay redirectPage, usar el default según el rol
            const defaultPage = getDefaultRedirect(role);
            console.log(`🔄 Redirigiendo a página por defecto: ${defaultPage}`);
            setCurrentPage(defaultPage);
        }
    };

    // =========================================================================
    // 5. RENDERIZADO SEGÚN LA PÁGINA ACTUAL
    // =========================================================================

    const renderPage = () => {
        switch (currentPage) {
            // -----------------------------------------------------------------
            // PÁGINA: HOME (Principal)
            // -----------------------------------------------------------------
            case 'home':
                return (
                    <>
                        <Header onLoginClick={goToLogin} />
                        <MainContent onServiciosClick={goToServicios} />
                        <Footer />
                    </>
                );

            // -----------------------------------------------------------------
            // PÁGINA: LOGIN/REGISTRO
            // -----------------------------------------------------------------
            case 'login':
                return (
                    <LoginPage 
                        onBackToHome={goToHome}
                        onLoginSuccess={handleLoginSuccess}  // ← IMPORTANTE: Pasar el manejador
                    />
                );

            // -----------------------------------------------------------------
            // PÁGINA: SERVICIOS PÚBLICOS (sin login)
            // -----------------------------------------------------------------
            case 'servicios':
                return (
                    <ServiciosPage 
                        onBackToHome={goToHome}
                        onGoToLogin={goToLogin}
                    />
                );

            // -----------------------------------------------------------------
            // PÁGINA: SERVICIOS PARA CLIENTES (requiere login)
            // -----------------------------------------------------------------
            case 'servicios-cliente':
                // Verificación de seguridad
                if (!isAuthenticated) {
                    console.warn('⚠️ Intento de acceso sin autenticación');
                    goToLogin();
                    return null;
                }

                return (
                    <ServiciosClientePage 
                        onBackToHome={goToHome}
                        onCotizacion={goToCotizacion}
                        onPerfil={goToPerfil}
                    />
                );

            // -----------------------------------------------------------------
            // PÁGINA: REPORTES (admin) - PRÓXIMAMENTE
            // -----------------------------------------------------------------
            case 'reportes':
                // Verificación de permisos
                if (!isAuthenticated || user?.role !== 'admin') {
                    console.warn('⚠️ Acceso no autorizado a reportes');
                    goToHome();
                    return null;
                }

                return (
                    <div style={{
                        minHeight: '100vh',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        flexDirection: 'column',
                        gap: '20px',
                        padding: '20px'
                    }}>
                        <h1 style={{ fontSize: '48px' }}>📊 Panel de Reportes</h1>
                        <p style={{ fontSize: '18px', color: '#666' }}>
                            Bienvenido, {user?.name}
                        </p>
                        <p style={{ fontSize: '16px', color: '#999' }}>
                            Página próximamente...
                        </p>
                        <button 
                            onClick={goToHome}
                            style={{
                                padding: '12px 30px',
                                background: '#0099ff',
                                color: 'white',
                                border: 'none',
                                borderRadius: '25px',
                                fontSize: '16px',
                                cursor: 'pointer',
                                transition: 'all 0.3s ease'
                            }}
                            onMouseEnter={(e) => e.target.style.background = '#0077cc'}
                            onMouseLeave={(e) => e.target.style.background = '#0099ff'}
                        >
                            Volver al inicio
                        </button>
                    </div>
                );

            // -----------------------------------------------------------------
            // PÁGINA: TAREAS (trabajador) - PRÓXIMAMENTE
            // -----------------------------------------------------------------
            case 'tareas':
                // Verificación de permisos
                if (!isAuthenticated || user?.role !== 'trabajador') {
                    console.warn('⚠️ Acceso no autorizado a tareas');
                    goToHome();
                    return null;
                }

                return (
                    <div style={{
                        minHeight: '100vh',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        flexDirection: 'column',
                        gap: '20px',
                        padding: '20px'
                    }}>
                        <h1 style={{ fontSize: '48px' }}>📋 Panel de Tareas</h1>
                        <p style={{ fontSize: '18px', color: '#666' }}>
                            Bienvenido, {user?.name}
                        </p>
                        <p style={{ fontSize: '16px', color: '#999' }}>
                            Página próximamente...
                        </p>
                        <button 
                            onClick={goToHome}
                            style={{
                                padding: '12px 30px',
                                background: '#0099ff',
                                color: 'white',
                                border: 'none',
                                borderRadius: '25px',
                                fontSize: '16px',
                                cursor: 'pointer',
                                transition: 'all 0.3s ease'
                            }}
                            onMouseEnter={(e) => e.target.style.background = '#0077cc'}
                            onMouseLeave={(e) => e.target.style.background = '#0099ff'}
                        >
                            Volver al inicio
                        </button>
                    </div>
                );

            // -----------------------------------------------------------------
            // PÁGINA POR DEFECTO: HOME
            // -----------------------------------------------------------------
            default:
                return (
                    <>
                        <Header onLoginClick={goToLogin} />
                        <MainContent onServiciosClick={goToServicios} />
                        <Footer />
                    </>
                );
        }
    };

    // =========================================================================
    // 6. RENDERIZADO PRINCIPAL
    // =========================================================================

    return (
        <div className="app" style={{
            minHeight: '100vh',
            display: 'flex',
            flexDirection: 'column'
        }}>
            {renderPage()}

            {/* INDICADOR DE SESIÓN (Para debugging - puedes quitarlo en producción) */}
            {isAuthenticated && (
                <div style={{
                    position: 'fixed',
                    top: '10px',
                    left: '10px',
                    background: 'rgba(0, 153, 255, 0.9)',
                    color: 'white',
                    padding: '8px 15px',
                    borderRadius: '20px',
                    fontSize: '12px',
                    zIndex: 10000,
                    boxShadow: '0 4px 15px rgba(0, 0, 0, 0.2)',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '8px'
                }}>
                    <span>👤</span>
                    <span>
                        {user?.name || user?.email} 
                        <strong style={{ marginLeft: '5px' }}>({user?.role})</strong>
                    </span>
                    <span style={{ 
                        marginLeft: '8px', 
                        fontSize: '10px', 
                        opacity: 0.8 
                    }}>
                        Página: {currentPage}
                    </span>
                </div>
            )}
        </div>
    );
};

